namespace {
std::string Bytes(const fs::path& path){std::ifstream in(path,std::ios::binary);return std::string((std::istreambuf_iterator<char>(in)),{});}
void Put(const fs::path& file,const std::string& bytes){std::ofstream out(file,std::ios::binary|std::ios::trunc);out<<bytes;if(!out)throw std::runtime_error("v062 fixture write");}
}
void RunV062StorageTests(const fs::path& root,std::ostream& report){
    auto check=[&](bool ok,const char* label){if(!ok)throw std::runtime_error(label);report<<"PASS: v062 "<<label<<std::endl;};
    auto folder=root/L"v062-storage";fs::create_directories(folder);auto file=folder/L"settings.json";
    // Explicitly reset only this test's known files, preserving all real settings.
    for(auto name:{L"settings.json",L"ocr-settings.json",L"stage3-settings.json",L"backups.json",L"IdDisplayNames.json"}){auto path=folder/name;if(fs::is_directory(path))fs::remove(path);else fs::remove(path);}
    auto ocr=std::string(R"({"version":1,"fps":7,"seconds":8,"always":true})");auto recording=std::string(R"({"version":1,"photoFolder":"D:\\写真","saveUserIds":false,"saveGroupIds":true})");
    Put(file,R"({"version":3,"thumbnailCacheMB":123})");Put(folder/L"ocr-settings.json",ocr);Put(folder/L"stage3-settings.json",recording);bool legacy=false;
    auto loaded=ReadSettingsSection(folder,L"ocr",L"ocr-settings.json",legacy);check(legacy&&loaded==ocr,"legacy OCR settings read without modifying the old file");WriteSettingsSection(folder,L"ocr",loaded,L"ocr-settings.json");
    loaded=ReadSettingsSection(folder,L"recording",L"stage3-settings.json",legacy);check(legacy&&loaded==recording,"legacy recording settings read intact");WriteSettingsSection(folder,L"recording",loaded,L"stage3-settings.json");
    check(!fs::exists(folder/L"ocr-settings.json")&&!fs::exists(folder/L"stage3-settings.json")&&ParseViewerSettings(Bytes(file)).cacheMB==123,"verified settings migration archives old files and preserves UI values");
    ViewerSettings ui;ui.cacheMB=144;WriteViewerSettingsFile(file,SerializeViewerSettings(ui));auto json=JsonObject::Parse(winrt::to_hstring(Bytes(file)));check(json.GetNamedNumber(L"version")==4&&json.GetNamedObject(L"ocr").GetNamedNumber(L"fps")==7&&json.GetNamedObject(L"recording").GetNamedBoolean(L"saveGroupIds"),"UI saves preserve OCR and recording sections");
    std::exception_ptr failure;std::mutex errors;auto work=[&](int mode){auto init=RoInitialize(RO_INIT_MULTITHREADED);try{for(int i=0;i<12;++i){if(mode==0){ViewerSettings v;v.cacheMB=150+i;WriteViewerSettingsFile(file,SerializeViewerSettings(v));}else WriteSettingsSection(folder,mode==1?L"ocr":L"recording",mode==1?ocr:recording);}}catch(...){std::lock_guard<std::mutex> lock(errors);failure=std::current_exception();}if(SUCCEEDED(init))RoUninitialize();};
    std::thread a(work,0),b(work,1),c(work,2);a.join();b.join();c.join();if(failure)std::rethrow_exception(failure);json=JsonObject::Parse(winrt::to_hstring(Bytes(file)));check(ParseViewerSettings(Bytes(file)).cacheMB==161&&json.HasKey(L"ocr")&&json.HasKey(L"recording"),"concurrent settings updates preserve all three sections");
    Put(file,"broken");Put(folder/L"ocr-settings.json",ocr);bool refused=false;try{WriteSettingsSection(folder,L"ocr",ocr,L"ocr-settings.json");}catch(...){refused=true;}check(refused&&Bytes(file)=="broken"&&Bytes(folder/L"ocr-settings.json")==ocr,"corrupt unified settings and old file are preserved on write failure");fs::remove(file);fs::create_directory(file);refused=false;try{WriteSettingsSection(folder,L"ocr",ocr);}catch(...){refused=true;}check(refused&&fs::is_directory(file),"unwritable settings destination is not replaced");fs::remove(file);
    Put(file,SerializeViewerSettings(ui));auto beforeFailure=Bytes(file);check(SetFileAttributesW(file.c_str(),FILE_ATTRIBUTE_READONLY)!=FALSE,"readonly settings failure fixture enabled");
    refused=false;try{WriteSettingsSection(folder,L"ocr",ocr);}catch(...){refused=true;}SetFileAttributesW(file.c_str(),FILE_ATTRIBUTE_NORMAL);bool temporary=false;for(auto& entry:fs::directory_iterator(folder))if(entry.path().extension()==L".tmp")temporary=true;
    check(refused&&Bytes(file)==beforeFailure&&!temporary,"atomic replacement failure keeps settings and cleans only its owned temporary file");
    auto ledger=folder/L"backups.json";auto newLedger=folder/L"Data"/L"backups.json";fs::remove(newLedger);Put(ledger,R"({"version":1,"entries":[]})");auto original=Bytes(ledger);auto moved=AppDataFile(folder,L"backups.json");check(moved==newLedger&&Bytes(moved)==original&&!fs::exists(ledger)&&ReadBackupLedger(moved).empty(),"backup ledger migrates losslessly into Data and remains readable");
    auto alias=folder/L"IdDisplayNames.json";auto newAlias=folder/L"Data"/L"IdDisplayNames.json";IdNameTable names{{L"grp_aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa",L"表示名"}};Put(alias,SerializeIdNames(names));fs::remove(newAlias);moved=AppDataFile(folder,L"IdDisplayNames.json");check(ParseIdNames(Bytes(moved)).names==names&&!fs::exists(alias),"independent Unicode ID table migrates without changing its import format");
    fs::remove(newAlias);Put(alias,"broken legacy");check(AppDataFile(folder,L"IdDisplayNames.json")==alias&&Bytes(alias)=="broken legacy","unparseable legacy file is preserved without migration");fs::remove(alias);
    Put(newAlias,SerializeIdNames(names));Put(alias,SerializeIdNames({{L"grp_aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa",L"旧名"}}));check(AppDataFile(folder,L"IdDisplayNames.json")==newAlias&&ParseIdNames(Bytes(newAlias)).names==names&&!fs::exists(alias),"existing Data file wins and the old conflicting table is archived");
}
void RunV062UiTests(const fs::path& root,std::ostream& report){
    auto check=[&](bool ok,const char* label){if(!ok)throw std::runtime_error(label);report<<"PASS: v062 "<<label<<std::endl;};auto pump=[](){MSG m{};while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}};auto wait=[&](auto ready){auto end=GetTickCount64()+20000;while(!ready()){pump();if(GetTickCount64()>end)throw std::runtime_error("v062 timeout");Sleep(10);}};
    KillTimer(app.window,RecordTimer);struct Restore{~Restore(){ClearBackdrop(false);app.diskCache=false;app.darkTheme=false;ConfigureDiskCache();SetTimer(app.window,RecordTimer,500,nullptr);}} restore;
    auto sample=root.parent_path().parent_path().parent_path()/L"Images"/L"back_img.webp";std::vector<std::wstring> copies;
    for(int i=0;i<5;++i){RequestBackdrop(sample.wstring());wait([&]{return !app.backgroundLoading;});check(HasBackdrop(),"repeated background application succeeds");copies.push_back(app.backgroundPath);}
    check(!fs::exists(copies[0])&&!fs::exists(copies[1])&&fs::exists(copies[2])&&fs::exists(copies[3])&&fs::exists(copies[4]),"only the current and previous two managed backgrounds remain");
    auto protectedFile=copies[2];{std::ofstream changed(protectedFile,std::ios::binary|std::ios::app);changed<<"external modification";}
    RequestBackdrop(sample.wstring());wait([&]{return !app.backgroundLoading;});RequestBackdrop(sample.wstring());wait([&]{return !app.backgroundLoading;});check(fs::exists(protectedFile),"externally modified managed image is excluded from automatic deletion");
    auto unmanaged=root/L"KuniVRCPhotEditor_Background_user.webp";fs::copy_file(sample,unmanaged,fs::copy_options::overwrite_existing);RequestBackdrop(sample.wstring());wait([&]{return !app.backgroundLoading;});check(fs::exists(unmanaged)&&fs::exists(protectedFile),"user image names and modified copies remain protected across later changes");
    auto valid=app.backgroundPath;RequestBackdrop((root/L"v060-bad.png").wstring());wait([&]{return !app.backgroundLoading;});check(app.backgroundPath==valid&&fs::exists(valid),"failed background application never prunes the current image");
    app.diskCache=true;app.bookmarkCache=false;app.diskCacheVisits=2;app.diskCacheMiB=128;ConfigureDiskCache();app.disk.WaitIdle();auto folder=root/L"v062-cache-images";fs::create_directories(folder);auto image=folder/L"source.png";fs::copy_file(root/L"v060-images"/L"transparent.png",image,fs::copy_options::overwrite_existing);app.disk.Visit(folder.wstring());app.disk.Visit(folder.wstring());Pixels p{4,4,std::vector<BYTE>(64,255)};app.disk.Put(ThumbnailCache::Key(image.wstring())+L"|256x256|v2",image.wstring(),p);
    std::vector<DiskThumbnailCache::FolderStatus> rows;wait([&]{return app.disk.GetFolders(rows);});auto found=std::find_if(rows.begin(),rows.end(),[&](auto& row){return SameFolderAddress(row.folder,folder.wstring());});check(found!=rows.end()&&found->entries==1&&found->bytes>=64,"cache exposes indexed source-folder counts and bytes");
    bool shown=false;ShowDiskCacheDialog([&](HWND h){auto listing=Text(GetDlgItem(h,2110));auto address=NormalizeFolderAddress(folder.wstring());for(auto& c:address)c=wchar_t(towlower(c));shown=listing.find(address)!=std::wstring::npos&&listing.find(L"1枚")!=std::wstring::npos;CaptureV0412Ui(root/L"v062-disk-folders.png",h);});check(shown,"disk cache dialog displays stored source folders, image counts and size");
    app.disk.Clear();app.disk.WaitIdle();wait([&]{return app.disk.GetFolders(rows);});check(rows.empty(),"cache deletion also removes the displayed folder inventory");
}
int V062Test(){auto root=app.settings.parent_path();std::ofstream report(root/L"v062-result.txt");try{RunV062StorageTests(root,report);RunV060UiTests(root,report);RunV062UiTests(root,report);report<<"ALL PASSED\n";return 0;}catch(const std::exception& e){report<<"FAIL: "<<e.what()<<std::endl;return 1;}}
